#!/bin/bash
# Finetune the FK-adapted How2Sign SLT model (finetune_h2s_fkpose epoch 14,
# itself from the official How2Sign pose-only model) directly on the 2308
# How2Sign TEST clips generated by DETO_RVQ_Hier_T5_h2s_tokfull (SOKE FK ->
# rtmpose2d, per-rank folders symlinked into rtmpose2d/test).
# NOTE: train == test here (--train_label_path labels.test), so the test BLEU
# printed each epoch is a fit/memorization number, not a held-out score.
#   bash script/finetune_h2s_on_test_deto_hier_t5_tokfull.sh [gpus]   # default 2,3
set -e

gpus=${1:-2,3}

pose_root=/home/student/hwu/Workplace/MotionGPT/results/mgpt/DETO_RVQ_Hier_T5_h2s_tokfull/rtmpose2d
ckpt_path=/data/hwu/Uni_sign_repo/out/finetune_h2s_fkpose/checkpoint_14.pth
output_dir=/data/hwu/Uni_sign_repo/out/finetune_h2s_on_test_deto_hier_t5_tokfull

mkdir -p $pose_root/test
find $pose_root/test_rank_* -name '*.pkl' -exec ln -sf -t $pose_root/test {} +
echo "test: $(ls $pose_root/test | wc -l) pose pkls"

mkdir -p $output_dir

# --pose_root_override without {}: the train phase reads the same test folder
deepspeed --include localhost:$gpus --master_port 29516 fine_tuning.py \
  --batch-size 16 \
  --gradient-accumulation-steps 1 \
  --epochs 20 \
  --opt AdamW \
  --lr 3e-4 \
  --dataset How2Sign \
  --task SLT \
  --finetune $ckpt_path \
  --output_dir $output_dir \
  --train_label_path ./data/How2Sign/labels.test \
  --pose_root_override $pose_root/test
